// Arma el reporte de observabilidad (Execution Log) del agente
const agente = $input.first().json;
const entrada = $('Chat de Entrada').first().json;
const pasos = agente.intermediateSteps || [];
const esc = (v) => String(typeof v === 'string' ? v : JSON.stringify(v, null, 2))
  .replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;');

let filas = pasos.map((p, i) => `
  <tr>
    <td>${i + 1}</td>
    <td><b>${esc(p.action?.tool ?? '-')}</b></td>
    <td><pre>${esc(p.action?.toolInput ?? '-')}</pre></td>
    <td><pre>${esc(p.observation ?? '-')}</pre></td>
  </tr>`).join('');

const usoHerramienta = pasos.length > 0;
const html = `
<h2>Reporte de Observabilidad - Agente de Calificación de Leads</h2>
<p><b>Fecha:</b> ${$now.setZone('America/Argentina/Buenos_Aires').toFormat('yyyy-MM-dd HH:mm:ss')}<br>
<b>Session ID:</b> ${esc(entrada.sessionId)}<br>
<b>Ejecución n8n:</b> ${$execution.id}<br>
<b>Herramienta activada:</b> ${usoHerramienta ? 'SÍ (' + pasos.length + ' llamada/s)' : 'NO'}</p>
<h3>Mensaje del prospecto</h3><blockquote>${esc(entrada.chatInput)}</blockquote>
<h3>Respuesta final del agente</h3><blockquote>${esc(agente.output)}</blockquote>
<h3>Traza de razonamiento (intermediate steps)</h3>
${usoHerramienta ? `<table border="1" cellpadding="6" cellspacing="0">
<tr><th>#</th><th>Herramienta</th><th>Entrada (decidida por la IA)</th><th>Resultado</th></tr>${filas}</table>`
 : '<p>El agente resolvió la consulta sin invocar herramientas.</p>'}`;

return [{ json: {
  asunto: `[Agente Leads] ${usoHerramienta ? 'Lead registrado' : 'Conversación sin registro'} - ${entrada.sessionId}`,
  html
}}];
